const { ethers } = require("hardhat");
const { poseidonContract } = require("circomlibjs");
const { initPoseidon, MERKLE_TREE_HEIGHT } = require("../src");

async function deployVesper() {
  await initPoseidon();
  const [owner, alice, bob, relayer, carol] = await ethers.getSigners();

  const hasherFactory = new ethers.ContractFactory(poseidonContract.generateABI(2), poseidonContract.createCode(2), owner);
  const hasher = await hasherFactory.deploy();

  // Generated by scripts/build-circuit.sh
  const verifier = await ethers.deployContract("Groth16Verifier");

  const tsla = await ethers.deployContract("MockStockToken", ["Tesla Stock Token", "TSLA"]);
  const aapl = await ethers.deployContract("MockStockToken", ["Apple Stock Token", "AAPL"]);
  const cap = ethers.parseEther("1000");

  // Initial assets are set in the constructor (later changes wait ADMIN_DELAY).
  const pool = await ethers.deployContract("VesperPool", [
    await verifier.getAddress(),
    await hasher.getAddress(),
    MERKLE_TREE_HEIGHT,
    owner.address,
    owner.address, // aspPostman
    [await tsla.getAddress(), await aapl.getAddress()],
    [cap, cap],
  ]);

  for (const user of [alice, bob, carol]) {
    for (const t of [tsla, aapl]) {
      await t.mint(user.address, ethers.parseEther("10000"));
      await t.connect(user).approve(await pool.getAddress(), ethers.MaxUint256);
    }
  }

  const { chainId } = await ethers.provider.getNetwork();
  return { owner, alice, bob, relayer, carol, hasher, verifier, pool, tsla, aapl, chainId };
}

/** Schedules an admin change, waits out the delay, executes it. */
async function adminChange(pool, signer, fn, args) {
  const { time } = require("@nomicfoundation/hardhat-toolbox/network-helpers");
  const data = pool.interface.encodeFunctionData(fn, args);
  await (await pool.connect(signer).scheduleChange(data)).wait();
  await time.increase(Number(await pool.ADMIN_DELAY()));
  return (await pool.connect(signer).executeChange(data)).wait();
}

module.exports = { deployVesper, adminChange };

// ---- compliance helpers ----
const src = require("../src");

/** Publishes an association set approving every deposit so far (except `except` labels). */
async function approveAll(ctx, { except = [] } = {}) {
  const skip = new Set(except.map(BigInt));
  const labels = (await src.fetchDeposits(ctx.pool)).map((d) => d.label).filter((l) => !skip.has(l));
  if (!labels.length) return null;
  const root = src.associationTree(labels).root();
  await (await ctx.pool.connect(ctx.owner).updateAssociationSet(root, labels, "test")).wait();
  return root;
}

/**
 * prepareTransaction for tests: same arguments, but fills in the current association
 * set automatically (unless `asp` or `exit` is given), so payouts prove approval.
 */
async function prepareTransaction(opts) {
  if (opts.asp === undefined && !opts.exit) opts = { ...opts, asp: await src.fetchAssociationSet(opts.pool) };
  return src.prepareTransaction(opts);
}

module.exports.approveAll = approveAll;
module.exports.prepareTransaction = prepareTransaction;
